export function canSwipe(routes,route,blocked=false){return !blocked&&routes.includes(route)}
export function enablePageSwipe(routes){const main=document.querySelector('#app'),footer=document.querySelector('#mobile-navigation');let start=null,suppressClick=false;const enabled=()=>canSwipe(routes,location.hash.slice(1),document.body.classList.contains('login-screen')||!!main.querySelector('.table-stage,[data-training-active],.training-area')||!!document.querySelector('dialog[open]'));for(const surface of [main,footer]){if(!surface)continue;surface.style.touchAction='pan-y';surface.addEventListener('pointerdown',e=>{start=null;suppressClick=false;if(!enabled()||e.button!==0||e.target.closest('input,textarea,select,[data-no-swipe]'))return;start={id:e.pointerId,x:e.clientX,y:e.clientY}});surface.addEventListener('pointerup',e=>{if(!start||e.pointerId!==start.id)return;const x=e.clientX-start.x,y=e.clientY-start.y;start=null;if(!enabled()||Math.abs(x)<55||Math.abs(x)<Math.abs(y)*1.4)return;const i=routes.indexOf(location.hash.slice(1)),next=i+(x<0?1:-1);if(next>=0&&next<routes.length){location.hash=routes[next];suppressClick=true}});surface.addEventListener('pointercancel',()=>{start=null;suppressClick=false});surface.addEventListener('click',e=>{if(suppressClick){e.preventDefault();e.stopImmediatePropagation();suppressClick=false}},true)}window.addEventListener('hashchange',()=>{start=null})}
